// Endereços desta instalação (detalhes em n8n/README.md).
const SUPABASE_URL = 'https://pcjyqwiuqphuiqgfvxqj.supabase.co';
// Endereço público do site, de onde sai o link do convite:
const URL_SITE = 'https://troque-pelo-endereco-do-site.com';

if (URL_SITE.includes('troque-pelo-endereco')) return [];
return [{ json: { supabase_url: SUPABASE_URL.replace(/\/+$/, ''), site: URL_SITE.replace(/\/+$/, '') } }];

const { site } = $('Configurar').first().json;
const PAPEL = { administrador: 'Administrador', advogado: 'Advogado', assistente: 'Assistente', leitura: 'Leitura' };
const esc = s => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const saida = [];
for (const item of $input.all()) {
  const lista = Array.isArray(item.json) ? item.json : [item.json];
  for (const c of lista) {
    if (!c || !c.id || !c.email || !c.token) continue;
    const link = site + '/convite/' + c.token;
    const validade = DateTime.fromISO(String(c.expira_em)).setZone('America/Sao_Paulo').toFormat('dd/MM/yyyy');
    const html = '<div style="font-family:Arial,sans-serif;font-size:14px;color:#222">'
      + '<h2>Convite para o Despert</h2>'
      + '<p>' + (c.convidado_por ? esc(c.convidado_por) + ' convidou você' : 'Você foi convidado(a)')
      + ' para a equipe <b>' + esc(c.organizacao) + '</b> no Despert, como <b>' + esc(PAPEL[c.papel] || c.papel) + '</b>.</p>'
      + '<p><a href="' + esc(link) + '" style="display:inline-block;padding:10px 16px;background:#0b2545;color:#fff;text-decoration:none;border-radius:6px">Aceitar o convite</a></p>'
      + '<p>Se ainda não tem conta, crie uma com este e-mail (' + esc(c.email) + ') pelo próprio link. O convite vale até ' + esc(validade) + '.</p>'
      + '<p style="color:#777;font-size:12px">Não esperava este convite? Pode ignorar este e-mail.</p></div>';
    saida.push({ json: { id: c.id, email: c.email, assunto: 'Convite para a equipe ' + c.organizacao + ' no Despert', html } });
  }
}
return saida;

// Só marca como enviado o que o Gmail aceitou; o resto tenta de novo na próxima rodada.
const convites = $('Montar Convites').all();
return $input.all()
  .map((item, i) => (item.json.error || !convites[i] ? null : { json: { convite: convites[i].json.id } }))
  .filter(Boolean);
